[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CoinTracker Pro — Cryptocurrency Prices, Charts and Market Capitalizations</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
/* ===== Design Tokens (OKLCH + hex fallback) ===== */
:root {
  --brand-blue: #3861FB;        /* oklch(52% 0.23 265) */
  --brand-blue-hover: #2950e0;  /* oklch(47% 0.23 265) */
  --brand-blue-light: #eef1fe;  /* oklch(96% 0.02 265) */
  --dark-navy: #0D1421;         /* oklch(15% 0.03 260) */
  --text-primary: #222531;      /* oklch(22% 0.02 260) */
  --text-secondary: #808A9D;    /* oklch(62% 0.02 260) */
  --text-tertiary: #9ba4b5;     /* oklch(68% 0.015 260) */
  --bg-primary: #ffffff;
  --bg-secondary: #f8f9fc;      /* oklch(98% 0.005 265) */
  --bg-tertiary: #eff1f5;       /* oklch(95% 0.008 265) */
  --border-color: #e8eaf2;      /* oklch(93% 0.008 265) */
  --green: #16c784;             /* oklch(72% 0.17 155) */
  --green-bg: rgba(22,199,132,0.08);
  --red: #ea3943;               /* oklch(58% 0.22 22) */
  --red-bg: rgba(234,57,67,0.08);
  --yellow: #f0b90b;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 2px 8px rgba(0,0,0,0.06);
  --shadow-lg: 0 4px 16px rgba(0,0,0,0.08);
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-mono: 'Inter', ui-monospace, SFMono-Regular, monospace;
}

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

html { font-size: 14px; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }

body {
  font-family: var(--font);
  color: var(--text-primary);
  background: var(--bg-secondary);
  line-height: 1.5;
  min-height: 100vh;
}

a { color: var(--brand-blue); text-decoration: none; }
a:hover { text-decoration: underline; }

/* ===== Navigation ===== */
.navbar {
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
}
.navbar-inner {
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  height: 56px;
  gap: 8px;
}
.nav-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  font-size: 1.14rem;
  color: var(--dark-navy);
  white-space: nowrap;
  margin-right: 16px;
}
.nav-logo svg { flex-shrink: 0; }
.nav-links { display: flex; gap: 2px; flex: 1; }
.nav-link {
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 0.928rem;
  font-weight: 500;
  white-space: nowrap;
  transition: background 0.15s, color 0.15s;
  cursor: pointer;
  position: relative;
}
.nav-link:hover { background: var(--bg-tertiary); text-decoration: none; }
.nav-link .arrow { font-size: 0.7em; margin-left: 2px; opacity: 0.5; }
.nav-actions { display: flex; gap: 8px; margin-left: auto; }
.btn {
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-size: 0.857rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all 0.15s;
  font-family: var(--font);
}
.btn-outline {
  background: transparent;
  color: var(--brand-blue);
  border: 1px solid var(--brand-blue);
}
.btn-outline:hover { background: var(--brand-blue-light); }
.btn-primary {
  background: var(--brand-blue);
  color: #fff;
}
.btn-primary:hover { background: var(--brand-blue-hover); }

/* ===== Top Bar Metrics ===== */
.top-bar {
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);
}
.top-bar-inner {
  max-width: 1440px;
  margin: 0 auto;
  padding: 12px 24px;
  display: flex;
  align-items: center;
  gap: 32px;
  overflow-x: auto;
}
.metric {
  display: flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
}
.metric-label {
  font-size: 0.785rem;
  color: var(--text-secondary);
  font-weight: 500;
}
.metric-value {
  font-size: 0.928rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.metric-change {
  font-size: 0.785rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  padding: 1px 5px;
  border-radius: 3px;
}
.metric-change.positive { color: var(--green); background: var(--green-bg); }
.metric-change.negative { color: var(--red); background: var(--red-bg); }
.metric-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 0.785rem;
  font-weight: 600;
}
.metric-badge.neutral { background: #f3f4f6; color: var(--text-secondary); }
.fear-greed-meter {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.714rem;
  font-weight: 700;
  color: #fff;
  background: linear-gradient(135deg, #f0b90b, #ea3943);
}
.metric-divider {
  width: 1px;
  height: 24px;
  background: var(--border-color);
}

/* ===== Promotional Banner ===== */
.promo-banner {
  background: linear-gradient(135deg, #1a1f36 0%, #0D1421 100%);
  color: #fff;
  overflow: hidden;
  position: relative;
}
.promo-track {
  display: flex;
  transition: transform 0.5s ease;
}
.promo-slide {
  min-width: 100%;
  padding: 16px 24px;
  max-width: 1440px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.promo-content { display: flex; align-items: center; gap: 12px; }
.promo-icon {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  background: rgba(56,97,251,0.3);
  display: flex;
  align-items: center;
  justify-content: center;
}
.promo-text { font-size: 0.928rem; font-weight: 500; }
.promo-text strong { color: var(--yellow); }
.promo-cta {
  background: var(--yellow);
  color: #000;
  padding: 6px 16px;
  border-radius: var(--radius-sm);
  font-size: 0.857rem;
  font-weight: 600;
  border: none;
  cursor: pointer;
  white-space: nowrap;
  transition: opacity 0.15s;
}
.promo-cta:hover { opacity: 0.9; }
.promo-dots {
  display: flex;
  gap: 6px;
  justify-content: center;
  padding: 8px 0 12px;
}
.promo-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: rgba(255,255,255,0.3);
  cursor: pointer;
  transition: background 0.2s;
}
.promo-dot.active { background: #fff; }
.promo-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(255,255,255,0.1);
  border: none;
  color: #fff;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  transition: background 0.15s;
}
.promo-nav:hover { background: rgba(255,255,255,0.2); }
.promo-nav.prev { left: 16px; }
.promo-nav.next { right: 16px; }

/* ===== AI Alerts Bar ===== */
.ai-bar {
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);
}
.ai-bar-inner {
  max-width: 1440px;
  margin: 0 auto;
  padding: 12px 24px;
}
.ai-prompt {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}
.ai-icon {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: linear-gradient(135deg, #3861FB, #7c3aed);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 0.857rem;
  flex-shrink: 0;
}
.ai-input {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  font-size: 0.857rem;
  cursor: pointer;
  transition: border-color 0.15s;
}
.ai-input:hover { border-color: var(--brand-blue); }
.ai-input .placeholder { color: var(--text-secondary); }
.ai-suggestions {
  display: flex;
  gap: 6px;
  overflow-x: auto;
  padding-bottom: 2px;
}
.ai-suggestion {
  padding: 4px 10px;
  border-radius: 20px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  font-size: 0.785rem;
  color: var(--text-secondary);
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.15s;
}
.ai-suggestion:hover {
  background: var(--brand-blue-light);
  border-color: var(--brand-blue);
  color: var(--brand-blue);
}

/* ===== Category & Network Tabs ===== */
.tabs-container {
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 56px;
  z-index: 90;
}
.tabs-inner {
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 24px;
}
.category-tabs {
  display: flex;
  gap: 2px;
  padding: 12px 0 0;
  overflow-x: auto;
  border-bottom: 1px solid var(--border-color);
}
.category-tab {
  padding: 8px 14px;
  font-size: 0.857rem;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: all 0.15s;
  white-space: nowrap;
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
  font-family: var(--font);
}
.category-tab:hover { color: var(--text-primary); }
.category-tab.active {
  color: var(--brand-blue);
  border-bottom-color: var(--brand-blue);
  font-weight: 600;
}
.network-tabs {
  display: flex;
  gap: 2px;
  padding: 10px 0;
  overflow-x: auto;
}
.network-tab {
  padding: 5px 12px;
  border-radius: 20px;
  font-size: 0.785rem;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  border: 1px solid var(--border-color);
  background: var(--bg-primary);
  transition: all 0.15s;
  white-space: nowrap;
  font-family: var(--font);
}
.network-tab:hover { border-color: var(--brand-blue); color: var(--brand-blue); }
.network-tab.active {
  background: var(--brand-blue-light);
  border-color: var(--brand-blue);
  color: var(--brand-blue);
  font-weight: 600;
}

/* ===== Table Controls ===== */
.table-controls {
  max-width: 1440px;
  margin: 0 auto;
  padding: 12px 24px 0;
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-secondary);
}
.control-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.857rem;
  font-weight: 500;
  cursor: pointer;
  border: 1px solid var(--border-color);
  background: var(--bg-primary);
  color: var(--text-primary);
  transition: all 0.15s;
  font-family: var(--font);
  position: relative;
}
.control-btn:hover { border-color: var(--brand-blue); color: var(--brand-blue); }
.control-btn.active { background: var(--brand-blue-light); border-color: var(--brand-blue); color: var(--brand-blue); }
.control-btn .arrow { font-size: 0.7em; opacity: 0.5; }
.control-btn svg { width: 14px; height: 14px; }
.table-count {
  margin-left: auto;
  font-size: 0.785rem;
  color: var(--text-secondary);
}

/* ===== Column Toggle Dropdown ===== */
.dropdown-panel {
  display: none;
  position: absolute;
  top: 100%;
  right: 0;
  margin-top: 4px;
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  padding: 8px;
  min-width: 200px;
  z-index: 200;
}
.dropdown-panel.open { display: block; }
.dropdown-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border-radius: var(--radius-sm);
  font-size: 0.857rem;
  cursor: pointer;
  transition: background 0.1s;
  color: var(--text-primary);
}
.dropdown-item:hover { background: var(--bg-secondary); }
.dropdown-item input[type="checkbox"] {
  accent-color: var(--brand-blue);
  width: 16px;
  height: 16px;
}

/* ===== Filters Panel ===== */
.filters-panel {
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 24px;
  overflow: hidden;
  max-height: 0;
  transition: max-height 0.3s ease, padding 0.3s ease;
  background: var(--bg-secondary);
}
.filters-panel.open {
  max-height: 200px;
  padding: 16px 24px;
}
.filters-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 12px;
}
.filter-group label {
  display: block;
  font-size: 0.785rem;
  font-weight: 500;
  color: var(--text-secondary);
  margin-bottom: 4px;
}
.filter-group select, .filter-group input {
  width: 100%;
  padding: 6px 10px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  font-size: 0.857rem;
  font-family: var(--font);
  color: var(--text-primary);
  background: var(--bg-primary);
}

/* ===== Crypto Rankings Table ===== */
.table-wrapper {
  background: var(--bg-primary);
  max-width: 1440px;
  margin: 0 auto;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  margin-top: 12px;
  overflow: hidden;
}
.crypto-table {
  width: 100%;
  border-collapse: collapse;
  font-variant-numeric: tabular-nums;
}
.crypto-table thead th {
  padding: 10px 12px;
  font-size: 0.714rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-secondary);
  text-align: right;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  white-space: nowrap;
  position: sticky;
  top: 0;
  z-index: 10;
}
.crypto-table thead th:first-child { text-align: center; width: 48px; }
.crypto-table thead th:nth-child(2) { text-align: left; }
.crypto-table thead th.sortable { cursor: pointer; }
.crypto-table thead th.sortable:hover { color: var(--brand-blue); }
.crypto-table thead th .sort-arrow { margin-left: 2px; font-size: 0.8em; }
.crypto-table tbody tr {
  border-bottom: 1px solid var(--border-color);
  transition: background 0.1s;
}
.crypto-table tbody tr:hover { background: var(--bg-secondary); }
.crypto-table tbody tr:last-child { border-bottom: none; }
.crypto-table tbody td {
  padding: 10px 12px;
  font-size: 0.928rem;
  text-align: right;
  white-space: nowrap;
}
.crypto-table tbody td:first-child {
  text-align: center;
  color: var(--text-secondary);
  font-size: 0.857rem;
}
.crypto-table tbody td:nth-child(2) { text-align: left; }

/* Name cell */
.coin-name-cell {
  display: flex;
  align-items: center;
  gap: 8px;
}
.coin-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.714rem;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}
.coin-name { font-weight: 600; color: var(--text-primary); }
.coin-symbol { color: var(--text-secondary); font-size: 0.785rem; margin-left: 4px; }

/* Percentage cells */
.pct-positive { color: var(--green); font-weight: 500; }
.pct-negative { color: var(--red); font-weight: 500; }

/* Sparkline cell */
.sparkline-cell { width: 120px; }
.sparkline-cell svg { display: block; }

/* Index row */
.index-row { background: var(--brand-blue-light); }
.index-row:hover { background: #dfe5fc; }
.index-label { font-weight: 600; color: var(--brand-blue); font-size: 0.857rem; }
.index-symbol { color: var(--brand-blue); font-size: 0.714rem; opacity: 0.7; }

/* ===== Pagination ===== */
.pagination {
  max-width: 1440px;
  margin: 0 auto;
  padding: 16px 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  background: var(--bg-secondary);
}
.page-btn {
  min-width: 36px;
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 0.857rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s;
  font-family: var(--font);
}
.page-btn:hover { border-color: var(--brand-blue); color: var(--brand-blue); }
.page-btn.active {
  background: var(--brand-blue);
  border-color: var(--brand-blue);
  color: #fff;
}
.page-dots { padding: 0 4px; color: var(--text-secondary); }
.page-info {
  font-size: 0.785rem;
  color: var(--text-secondary);
  margin-left: 16px;
}

/* ===== Market Summary ===== */
.market-summary {
  max-width: 1440px;
  margin: 24px auto 0;
  padding: 0 24px;
}
.summary-card {
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 24px;
}
.summary-card h2 {
  font-size: 1.14rem;
  font-weight: 700;
  margin-bottom: 12px;
  color: var(--text-primary);
}
.summary-text {
  font-size: 0.928rem;
  line-height: 1.7;
  color: var(--text-secondary);
}
.summary-text strong { color: var(--text-primary); font-weight: 600; }
.summary-more {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--brand-blue);
  font-size: 0.857rem;
  font-weight: 600;
  cursor: pointer;
  margin-top: 8px;
  background: none;
  border: none;
  font-family: var(--font);
}
.summary-more:hover { text-decoration: underline; }
.summary-extra {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}
.summary-extra.open { max-height: 300px; }
.summary-extra-inner {
  padding-top: 12px;
  border-top: 1px solid var(--border-color);
  margin-top: 12px;
  font-size: 0.928rem;
  line-height: 1.7;
  color: var(--text-secondary);
}
.summary-extra-inner strong { color: var(--text-primary); font-weight: 600; }

/* ===== Info Content ===== */
.info-content {
  max-width: 1440px;
  margin: 24px auto 0;
  padding: 0 24px;
}
.info-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}
.info-card {
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 24px;
}
.info-card h3 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--text-primary);
}
.info-card p {
  font-size: 0.857rem;
  line-height: 1.65;
  color: var(--text-secondary);
}

/* ===== Footer ===== */
.footer {
  margin-top: 48px;
  background: var(--bg-primary);
  border-top: 1px solid var(--border-color);
}
.footer-inner {
  max-width: 1440px;
  margin: 0 auto;
  padding: 40px 24px 24px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 32px;
  margin-bottom: 32px;
}
.footer-brand p {
  font-size: 0.857rem;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-top: 8px;
  max-width: 280px;
}
.footer-col h4 {
  font-size: 0.785rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-primary);
  margin-bottom: 12px;
}
.footer-col a {
  display: block;
  font-size: 0.857rem;
  color: var(--text-secondary);
  padding: 3px 0;
  transition: color 0.15s;
}
.footer-col a:hover { color: var(--brand-blue); text-decoration: none; }
.footer-bottom {
  border-top: 1px solid var(--border-color);
  padding-top: 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.785rem;
  color: var(--text-secondary);
}
.footer-socials { display: flex; gap: 12px; }
.footer-socials a { color: var(--text-secondary); font-size: 1.14rem; }
.footer-socials a:hover { color: var(--brand-blue); }

