// ===== Formatting helpers =====
function fmtPrice(p) {
  if (p >= 1000) return '$' + p.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});
  if (p >= 1) return '$' + p.toFixed(2);
  if (p >= 0.01) return '$' + p.toFixed(4);
  if (p >= 0.0001) return '$' + p.toFixed(6);
  return '$' + p.toFixed(8);
}
function fmtMcap(v) {
  if (v >= 1e12) return '$' + (v/1e12).toFixed(2) + 'T';
  if (v >= 1e9) return '$' + (v/1e9).toFixed(2) + 'B';
  if (v >= 1e6) return '$' + (v/1e6).toFixed(2) + 'M';
  return '$' + v.toLocaleString();
}
function fmtVol(v) {
  if (v >= 1e9) return '$' + (v/1e9).toFixed(2) + 'B';
  if (v >= 1e6) return '$' + (v/1e6).toFixed(2) + 'M';
  return '$' + v.toLocaleString();
}
function fmtPct(v) {
  const sign = v >= 0 ? '+' : '';
  const cls = v >= 0 ? 'pct-positive' : 'pct-negative';
  return `<span class="${cls}">${sign}${v.toFixed(2)}%</span>`;
}

// ===== Sparkline SVG generator =====
function genSparkline(trend, color) {
  const w = 120, h = 36, pts = 14;
  let points = [];
  let y = h / 2;
  for (let i = 0; i < pts; i++) {
    const x = (i / (pts - 1)) * w;
    const delta = trend === 'up' ? (Math.random() * 3 - 0.8) :
                  trend === 'down' ? (Math.random() * 3 - 2.2) :
                  (Math.random() * 2 - 1);
    y = Math.max(4, Math.min(h - 4, y - delta));
    points.push(`${x.toFixed(1)},${y.toFixed(1)}`);
  }
  const strokeColor = trend === 'up' ? 'var(--green)' : trend === 'down' ? 'var(--red)' : 'var(--text-secondary)';
  return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" fill="none"><polyline points="${points.join(' ')}" stroke="${strokeColor}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" fill="none"/></svg>`;
}

// ===== Render table =====
function renderTable() {
  const tbody = document.getElementById('cryptoTableBody');
  let html = '';

  // Index tracker row
  html += `<tr class="index-row">
    <td></td>
    <td><span class="index-label">CoinTracker 20 Index</span><br><span class="index-symbol">DTFCTP20</span></td>
    <td style="font-weight:600">$154.29</td>
    <td>${fmtPct(0.21)}</td>
    <td>${fmtPct(1.15)}</td>
    <td>${fmtPct(4.97)}</td>
    <td>—</td><td>—</td><td>—</td>
    <td class="sparkline-cell">${genSparkline('up','blue')}</td>
  </tr>`;

  // Coin rows
  COINS.forEach(c => {
    const initial = c.name.charAt(0);
    html += `<tr>
      <td>${c.rank}</td>
      <td><div class="coin-name-cell">
        <span class="coin-icon" style="background:${c.color}">${initial}</span>
        <span class="coin-name">${c.name}</span>
        <span class="coin-symbol">${c.sym}</span>
      </div></td>
      <td style="font-weight:600">${fmtPrice(c.price)}</td>
      <td>${fmtPct(c.h1)}</td>
      <td>${fmtPct(c.h24)}</td>
      <td>${fmtPct(c.d7)}</td>
      <td>${fmtMcap(c.mcap)}</td>
      <td>${fmtVol(c.vol)}</td>
      <td>${c.supply} ${c.supplyUnit}</td>
      <td class="sparkline-cell">${genSparkline(c.trend, c.color)}</td>
    </tr>`;
  });

  tbody.innerHTML = html;
}

// ===== Promo Banner Carousel =====
let promoSlide = 0;
const promoTotal = 3;
function goToPromo(idx) {
  promoSlide = idx;
  document.getElementById('promoTrack').style.transform = `translateX(-${idx * 100}%)`;
  document.querySelectorAll('.promo-dot').forEach((d,i) => d.classList.toggle('active', i===idx));
}
function slidePromo(dir) {
  goToPromo((promoSlide + dir + promoTotal) % promoTotal);
}
setInterval(() => slidePromo(1), 5000);

