  const selector = colMap[col];
  if (selector) {
    document.querySelectorAll(selector).forEach(el => {
      el.style.display = checked ? '' : 'none';
    });
    // Also hide the corresponding tbody cells
    const colIdx = Object.keys(colMap).indexOf(col);
    if (colIdx >= 0) {
      const adjustedIdx = colIdx + 3; // offset for rank, name, price columns
      document.querySelectorAll('#cryptoTableBody tr').forEach(row => {
        const cell = row.children[adjustedIdx];
        if (cell) cell.style.display = checked ? '' : 'none';
      });
    }
  }
});

// ===== Filters Toggle =====
function toggleFilters() {
  const panel = document.getElementById('filtersPanel');
  const btn = document.getElementById('filterBtn');
  panel.classList.toggle('open');
  btn.classList.toggle('active');
}

// ===== Summary Accordion =====
function toggleSummary() {
  const extra = document.getElementById('summaryExtra');
  const arrow = document.getElementById('summaryArrow');
  extra.classList.toggle('open');
  arrow.textContent = extra.classList.contains('open') ? '▴' : '▾';
}

// ===== Pagination =====
document.querySelectorAll('.page-btn').forEach(btn => {
  btn.addEventListener('click', function() {
    document.querySelectorAll('.page-btn').forEach(b => b.classList.remove('active'));
    this.classList.add('active');
  });
});

// ===== Close dropdowns on outside click =====
document.addEventListener('click', e => {
  if (!e.target.closest('#columnsBtn') && !e.target.closest('#columnsPanel')) {
    document.getElementById('columnsPanel').classList.remove('open');
  }
});

// ===== Init =====
renderTable();
</script>
</body>
</html>
